import pdfplumber
import pandas as pd
import json

def extract_pdf_data(pdf_path):
    employees = {}
    with pdfplumber.open(pdf_path) as pdf:
        for page in pdf.pages:
            tables = page.extract_tables()
            for table in tables:
                if not table:
                    continue
                # Assuming first row is header
                header = table[0]
                for row in table[1:]:
                    if not row or not any(row):
                        continue
                    # Create a dictionary for the employee
                    emp_data = dict(zip(header, row))
                    emp_id = emp_data.get('ID')
                    if emp_id:
                        # Convert numeric fields
                        for field in ['Salary', 'Years', 'Score']:
                            if field in emp_data and emp_data[field] is not None:
                                try:
                                    # Remove commas or currency symbols if any
                                    val = str(emp_data[field]).replace('$', '').replace(',', '')
                                    if '.' in val:
                                        emp_data[field] = float(val)
                                    else:
                                        emp_data[field] = int(val)
                                except ValueError:
                                    pass
                        employees[emp_id] = emp_data
    return employees

def extract_excel_data(xlsx_path):
    df = pd.read_excel(xlsx_path)
    # Convert DataFrame to dictionary keyed by ID
    employees = {}
    for _, row in df.iterrows():
        emp_data = row.to_dict()
        emp_id = emp_data.get('ID')
        if emp_id:
            employees[emp_id] = emp_data
    return employees

def compare_data(old_data, new_data):
    deleted_employees = []
    modified_employees = []

    # Check for deleted employees
    for emp_id in old_data:
        if emp_id not in new_data:
            deleted_employees.append(emp_id)
        else:
            # Check for modifications
            old_emp = old_data[emp_id]
            new_emp = new_data[emp_id]

            # Fields to compare (excluding ID)
            fields = set(old_emp.keys()) | set(new_emp.keys())
            fields.discard('ID')

            for field in sorted(fields):
                old_val = old_emp.get(field)
                new_val = new_emp.get(field)

                # Handle potential NaN from pandas
                if pd.isna(new_val):
                    new_val = None

                if old_val != new_val:
                    modified_employees.append({
                        "id": emp_id,
                        "field": field,
                        "old_value": old_val,
                        "new_value": new_val
                    })

    deleted_employees.sort()
    # Sort modified_employees by ID, then field
    modified_employees.sort(key=lambda x: (x['id'], x['field']))

    return deleted_employees, modified_employees

def main():
    pdf_path = '/root/employees_backup.pdf'
    xlsx_path = '/root/employees_current.xlsx'

    old_data = extract_pdf_data(pdf_path)
    new_data = extract_excel_data(xlsx_path)

    deleted, modified = compare_data(old_data, new_data)

    report = {
        "deleted_employees": deleted,
        "modified_employees": modified
    }

    with open('/root/diff_report.json', 'w') as f:
        json.dump(report, f, indent=2)

if __name__ == "__main__":
    main()

