import pdfplumber
import pandas as pd
import json
import numpy as np
import re

def extract_pdf_data(pdf_path):
    employees = {}
    # Regex to match the row format
    # ID First Last Dept Position Salary Years Location Score
    pattern = re.compile(r"(EMP\d{5})\s+(\S+)\s+(\S+)\s+(\S+)\s+(.+?)\s+([\d,]+)\s+(\d+)\s+(.+?)\s+(\d+(?:\.\d+)?)$")

    with pdfplumber.open(pdf_path) as pdf:
        for page in pdf.pages:
            text = page.extract_text()
            if not text:
                continue
            for line in text.split('\n'):
                line = line.strip()
                match = pattern.match(line)
                if match:
                    groups = match.groups()
                    emp_id = groups[0]

                    # Process salary
                    salary_str = groups[5].replace(',', '')
                    salary = int(salary_str) if salary_str.isdigit() else float(salary_str)

                    emp_data = {
                        'ID': emp_id,
                        'First': groups[1],
                        'Last': groups[2],
                        'Dept': groups[3],
                        'Position': groups[4],
                        'Salary': salary,
                        'Years': int(groups[6]),
                        'Location': groups[7],
                        'Score': float(groups[8])
                    }
