    pattern = re.compile(r"(EMP\d{5})\s+(\S+)\s+(\S+)\s+(\S+)\s+(.+?)\s+([\d,]+)\s+(\d+)\s+(.+?)\s+(\d+(?:\.\d+)?)$")

    with pdfplumber.open(pdf_path) as pdf:
        for page in pdf.pages:
            text = page.extract_text()
            if not text:
                continue
            for line in text.split('\n'):
                line = line.strip()
                match = pattern.match(line)
                if match:
                    groups = match.groups()
                    emp_id = groups[0]
                    salary_str = groups[5].replace(',', '')
                    salary = int(salary_str) if salary_str.isdigit() else float(salary_str)

                    emp_data = {
                        'ID': emp_id,
                        'First': groups[1],
                        'Last': groups[2],
                        'Dept': groups[3],
                        'Position': groups[4],
                        'Salary': salary,
                        'Years': int(groups[6]),
                        'Location': groups[7],
                        'Score': float(groups[8])
                    }
                    employees[emp_id] = emp_data
    return employees

def extract_excel_data(xlsx_path):
    df = pd.read_excel(xlsx_path)
    df = df[df['ID'].notna()]
    employees = {}
    for _, row in df.iterrows():
        emp_data = row.to_dict()
        emp_id = str(row['ID']).strip()
        if emp_id:
            for field in ['Salary', 'Years', 'Score']:
                if field in emp_data:
                    val = emp_data[field]
                    if pd.isna(val):
                        emp_data[field] = None
                    elif isinstance(val, (np.integer, np.floating)):
                        emp_data[field] = val.item()
            employees[emp_id] = emp_data
    return employees

def compare_data(old_data, new_data):
    deleted_employees = []
    modified_employees = []

    for emp_id in old_data:
        if emp_id not in new_data:
            deleted_employees.append(emp_id)
        else:
            old_emp = old_data[emp_id]
            new_emp = new_data[emp_id]
            fields = ['First', 'Last', 'Dept', 'Position', 'Salary', 'Years', 'Location', 'Score']

            for field in fields:
                old_val = old_emp.get(field)
                new_val = new_emp.get(field)

                if pd.isna(new_val): new_val = None

                is_diff = False
                if isinstance(old_val, (int, float)) and isinstance(new_val, (int, float)):
                    if abs(old_val - new_val) > 1e-9:
                        is_diff = True
                elif str(old_val) != str(new_val):
                    if isinstance(old_val, (int, float)):
                        try:
                            if abs(old_val - float(new_val)) > 1e-9:
                                is_diff = True
                        except:
                            is_diff = True
                    else:
                        is_diff = True

                if is_diff:
                    modified_employees.append({
                        "id": emp_id,
                        "field": field,
                        "old_value": old_val,
                        "new_value": new_val
                    })

    deleted_employees.sort()
    modified_employees.sort(key=lambda x: (x['id'], x['field']))
    return deleted_employees, modified_employees

