    old_data = extract_pdf_data('/root/employees_backup.pdf')
    new_data = extract_excel_data('/root/employees_current.xlsx')
    deleted, modified = compare_data(old_data, new_data)
    with open('/root/diff_report.json', 'w') as f:
        json.dump({"deleted_employees": deleted, "modified_employees": modified}, f, indent=2)

if __name__ == "__main__":
    main()

